import type {Employee} from '@/types/employee'

const API_URL = '/api/employees';

export const getEmployees = async (): Promise<Employee[]> =>{

    const response = await fetch(API_URL);
    if(!response.ok){
        throw new Error('Failed to fetch employees');
    }

    return response.json();
     
}


// here Omit is used because if you pass id then typescript will throw error because id is optional and it is generated by the server so we don't need to pass it while creating employee.
export const createEmployee = async (employee: Omit<Employee, "id">): Promise<Employee> => {
    const response = await fetch(API_URL, {
        method: 'POST',
        headers:{"Content-Type" : 'application/json'},
        body: JSON.stringify(employee)
    })
    if(!response.ok){
        throw new Error('Failed to create employee');
    }
    return response.json();
}


export const getEmployeeById = async (id:number): Promise<Employee> =>{
    const response = await fetch(`${API_URL}/${id}`);
    if(!response.ok){
        throw new Error('Failed to fetch employee');
    }
    return response.json();
}

export const updateEmployee = async (employee: Employee): Promise<Employee> => {
    const response = await fetch(`${API_URL}/${employee.id}`, {
        method: 'PUT',
        headers:{"Content-Type" : 'application/json'},
        body: JSON.stringify(employee)
    });
    if(!response.ok){
        throw new Error('Failed to update employee');
    }
    return response.json();
}

export const deleteEmployee = async (id: number): Promise<String> => {
    const response = await fetch(`${API_URL}/${id}`, {
        method: 'DELETE'
    });
    if(!response.ok){
        throw new Error('Failed to delete employee');
    }
    return response.text();
}
